def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def add_statement(out,term,support_ids):
    support=unique(support_ids)
    for row in out:
        if row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def answer_rows(value):
    if isinstance(value,list):
        return value
    if isinstance(value,dict):
        rows=value.get('answers')
        if isinstance(rows,list):
            return rows
        if isinstance(rows,dict):
            return list(rows.values())
        return list(value.values())
    return []

def answer_by_id(rows,qid):
    for row in rows:
        if isinstance(row,dict) and row.get('id')==qid:
            return row
    return None

def evidence_ids(answer):
    out=[]
    if not isinstance(answer,dict):
        return out
    evidence=answer.get('evidence',[])
    if isinstance(evidence,dict):
        evidence=[evidence]
    for item in evidence:
        if isinstance(item,dict):
            uid=item.get('unit_id')
            if uid not in out:
                out.append(uid)
    return out

def term_contains(value,name):
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def apply(inputs,premises):
    out=[]
    unresolved=[]
    source_output=inputs.get('source_output',{})
    if isinstance(source_output,dict):
        for row in source_output.get('statements',[]):
            if isinstance(row,dict) and isinstance(row.get('term'),list):
                add_statement(out,row.get('term'),row.get('support_ids',[]))
        for value in source_output.get('unresolved',[]):
            if value not in unresolved:
                unresolved.append(value)
    has_disposal=False
    for row in out:
        if term_contains(row.get('term'),'disposal_obligation'):
            has_disposal=True
    answer=answer_by_id(answer_rows(inputs.get('semantic_answers',[])),'complete_disposal_review_v4')
    if not has_disposal and isinstance(answer,dict):
        if answer.get('choice')=='none_in_complete_source':
            add_statement(out,['complete_source_no_disposal_obligation'],evidence_ids(answer))
        elif answer.get('choice')=='candidate_found':
            unresolved.append('A complete-source reader found a disposal candidate that the deterministic source program did not safely type; its action, material scope and trigger remain unresolved.')
    elif not has_disposal and answer is None:
        unresolved.append('Complete-source disposal review is pending; absence is not inferred from deterministic non-matching.')
    return {'statements':out,'complete':len(unresolved)==0,'unresolved':unresolved}

