def lower_text(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold().strip()

def has_any(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def add_statement(out,term,support_ids):
    support=unique(support_ids)
    for row in out:
        if row.get('term')==term:
            return
    out.append({'term':term,'support_ids':support})

def make_union(items):
    if not items:
        return None
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def make_and(items):
    if not items:
        return ['no_condition']
    value=items[0]
    i=1
    while i<len(items):
        value=['and_condition',value,items[i]]
        i+=1
    return value

def make_bundle(items):
    if not items:
        return ['confidential_information']
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def actor_for(text):
    if 'volunteer' in text:
        return ['named_recipient','Volunteer']
    if 'auditor' in text and 'receiving party' not in text:
        return ['named_recipient','Auditor']
    if 'visitor' in text and 'receiving party' not in text:
        return ['named_recipient','Visitor']
    return ['receiving_party']

def recipient_roles(text,owner):
    out=[]
    if has_any(text,['employee','staff','personnel']):
        out.append(['employees_of',owner])
    if 'director' in text:
        out.append(['directors_of',owner])
    if has_any(text,['officer','official']):
        out.append(['officers_of',owner])
    if has_any(text,['legal adviser','legal advisor','attorney','legal counsel']):
        out.append(['legal_advisors_of',owner])
    if has_any(text,['financial adviser','financial advisor']):
        out.append(['financial_advisors_of',owner])
    if has_any(text,['professional adviser','professional advisor']):
        out.append(['professional_advisors_of',owner])
    if 'accountant' in text:
        out.append(['accountants_of',owner])
    if 'consultant' in text:
        out.append(['consultants_of',owner])
    if 'contractor' in text:
        out.append(['independent_contractors_of',owner])
    if 'agent' in text:
        out.append(['agents_of',owner])
    if has_any(text,['lender','finance provider']):
        out.append(['lenders_of',owner])
    if not out and 'representative' in text:
        out.append(['representatives_of',owner])
    return out

def disclosure_conditions(text,raw):
    out=[]
    if has_any(text,['need to know','need-to-know','strict need to know','bona fide need']):
        out.append(['need_to_know',raw])
    if has_any(text,['extent necessary','extent absolutely necessary','reasonably necessary','disclosure is necessary','knowledge of the confidential information is reasonably necessary']):
        out.append(['extent_necessary',raw])
    if has_any(text,['written confidentiality agreement','written agreement with','signed the mandatory non-disclosure agreement','signed the mandatory nondisclosure agreement','bound to a duty of confidentiality','bound by obligations of confidentiality','treat the confidential information in accordance','treat the confidential information as confidential','advise such employees','complies with all the provisions of this agreement','obligated to protect']):
        out.append(['confidentiality_bound',raw])
    return make_and(out)

def parse_definition(raw,uid,out):
    text=lower_text(raw)
    if not has_any(text,['representative” means','representatives” means','"representative" means','"representatives" means']):
        return
    roles=recipient_roles(text,['party'])
    if roles:
        add_statement(out,['define_representative',['party'],make_union(roles)],[uid])

def parse_disclosure(raw,support,out):
    text=lower_text(raw)
    protected=has_any(text,['confidential information','such confidential information','said information','information it receives from','contents of the confidential information'])
    if not protected:
        return
    actor=actor_for(text)
    if has_any(text,['neither it nor its representatives','neither the receiving party nor its representatives']) and has_any(text,['any other person','any other organization','other person or organization']):
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        add_statement(out,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],['no_exceptions']],support)
        return
    if has_any(text,['reveal such confidential information to others','reveal confidential information to others']):
        add_statement(out,['prohibition',actor,['disclose',['confidential_information'],['outsiders_to',actor]],['no_condition'],['exception_set',['authorization_exception','source-stated authorization']]],support)
        return
    permission=has_any(text,['may disclose','may be disclosed','may share','will disclose information','restrict disclosure','restrict access','disclosed only to','do not apply to the disclosure'])
    if permission:
        roles=recipient_roles(text,['receiving_party'])
        if roles:
            add_statement(out,['permission',actor,['disclose',['confidential_information'],make_union(roles)],disclosure_conditions(text,raw)],support)
    negative=has_any(text,['shall not disclose','not disclose said information','not to disclose','agrees not to','will not provide confidential information','prohibited from disclosing'])
    general_recipient=has_any(text,['third party','third parties','any other person','any other organization'])
    if negative and general_recipient:
        exceptions=[]
        if has_any(text,['prior written consent','prior written agreement','prior written approval','expressly authorized in writing']):
            exceptions.append(['authorization_exception','source-stated written authorization'])
        if has_any(text,['required to analyze','required to fulfil','required to fulfill','required in the course of service']):
            exceptions.append(['purpose_exception','source-stated required activity'])
        if exceptions:
            ex=['exception_set',exceptions[0]]
            i=1
            while i<len(exceptions):
                ex=['add_exception',ex,exceptions[i]]
                i+=1
        else:
            ex=['no_exceptions']
        add_statement(out,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],ex],support)

def material_scope(text):
    items=[['confidential_information']]
    if has_any(text,['copy','copies','reproduction','record copy','backup','archive']):
        items.append(['copies_of',['confidential_information']])
    if has_any(text,['note','abstract','extract','analysis','study','summary','derivative']):
        items.append(['derivative_materials_of',['confidential_information']])
    return make_bundle(items)

def trigger_terms(text):
    out=[]
    if has_any(text,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship']):
        out.append(['relationship_nonformation_deadline'])
    if has_any(text,['termination of service','service terminates','termination of the actor’s service']):
        out.append(['service_termination'])
    if has_any(text,['termination/expiration of the business relation','termination or expiration of the business relation','termination of the business relationship','termination of the working relationship']):
        out.append(['relationship_termination'])
    if has_any(text,['termination of this agreement','termination ofthis agreement','expiration of this agreement','expiration or termination of this agreement','expiration or termination ofthis agreement','termination/expiration of this non-disclosure agreement']):
        out.append(['agreement_termination'])
    if 'completion of the purpose' in text:
        out.append(['purpose_completion'])
    if has_any(text,['upon request','at any time upon request','promptly upon request','request by','request of','request from']):
        out.append(['request_by',['disclosing_party']])
    return unique(out)

def trigger_value(items):
    if not items:
        return None
    value=items[0]
    i=1
    while i<len(items):
        value=['trigger_alternative',value,items[i]]
        i+=1
    return value

def parse_disposal(raw,support,out):
    text=lower_text(raw)
    if not has_any(text,['confidential information','information disclosed','information provided','copies thereof','materials which']):
        return
    triggers=trigger_terms(text)
    if not triggers:
        return
    do_return=has_any(text,['shall return','return to','returned to','promptly return','information will be returned'])
    do_destroy=has_any(text,['shall be destroyed','or destroy','destroy it','certify the destruction','ensure the destruction','promptly destroy']) and 'not destroyed' not in text
    if not do_return and not do_destroy:
        return
    info=material_scope(text)
    if do_return and do_destroy:
        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
    elif do_return:
        action=['return_to',info,['disclosing_party']]
    else:
        action=['destroy',info]
    add_statement(out,['disposal_obligation',actor_for(text),action,trigger_value(triggers),['no_exceptions']],support)

def parse_retention(raw,uid,out):
    text=lower_text(raw)
    actor=actor_for(text)
    info=material_scope(text)
    if has_any(text,['entitled to retain','may retain','may maintain a single copy','permitted to retain']):
        add_statement(out,['retention_permission',actor,info,['after_disposal'],['retention_condition',raw]],[uid])
    explicit_after=has_any(text,['without retaining any copies','without retaining any copy','no copies or records thereof shall be retained','no copy shall be retained']) or ('no copies' in text and 'shall be retained' in text)
    if explicit_after:
        add_statement(out,['retention_prohibition',actor,info,['after_disposal']],[uid])
    absolute=has_any(text,['not to make or retain copy','shall not retain any copy','must not retain any copy'])
    if 'will at any time' in text and 'retain' in text and 'confidential information' in text:
        absolute=True
    if 'will not' in text and 'preserve any confidential information' in text:
        absolute=True
    if absolute:
        add_statement(out,['absolute_retention_prohibition',actor,info],[uid])

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    out=[]
    seed=inputs.get('source_output',{})
    if isinstance(seed,dict):
        for row in seed.get('statements',[]):
            if isinstance(row,dict) and isinstance(row.get('term'),list):
                add_statement(out,row.get('term'),row.get('support_ids',[]))
    texts=[]
    ids=[]
    for span in spans:
        uid=span.get('id')
        raw=span.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        ids.append(uid)
        texts.append(raw)
        parse_definition(raw,uid,out)
        parse_disclosure(raw,[uid],out)
        parse_disposal(raw,[uid],out)
        parse_retention(raw,uid,out)
    i=0
    while i<len(texts):
        current=lower_text(texts[i])
        disclosure_header=current.endswith(':') and has_any(current,['may disclose','do not apply to the disclosure','shall be handled as follows'])
        if disclosure_header:
            j=i+1
            while j<len(texts) and j<=i+4:
                parse_disclosure(' '.join(texts[i:j+1]),ids[i:j+1],out)
                j+=1
        disposal_header=(current.endswith(':') and has_any(current,['return of confidential information','shall be returned','returned to','return or destroy'])) or (trigger_terms(current) and has_any(current,['return of confidential information','shall return','return to']) and not has_any(current,['or destroy','destroy it','ensure the destruction']))
        if disposal_header:
            j=i+1
            while j<len(texts) and j<=i+4:
                parse_disposal(' '.join(texts[i:j+1]),ids[i:j+1],out)
                j+=1
        i+=1
    return {'statements':out,'complete':True,'unresolved':[]}
